//! Tests for V8 Fast API callbacks generated by `#[jsg_method]`.

use std::cell::Cell;

use jsg::ExceptionType;
use jsg_macros::jsg_method;
use jsg_macros::jsg_resource;

#[jsg_resource]
struct FastResource {
    base: i32,
    touched: Cell<u32>,
}

#[jsg_resource]
impl FastResource {
    #[jsg_method]
    pub fn add(&self, a: i32, b: i32) -> i32 {
        self.base + a + b
    }

    #[jsg_method]
    pub fn id_i32(&self, x: i32) -> i32 {
        x
    }

    #[jsg_method]
    pub fn id_u32(&self, x: u32) -> u32 {
        x
    }

    #[jsg_method]
    pub fn id_f64(&self, x: f64) -> f64 {
        x
    }

    #[jsg_method]
    pub fn id_bool(&self, x: bool) -> bool {
        x
    }

    #[jsg_method]
    pub fn id_u8(&self, x: u8) -> u8 {
        x
    }

    #[jsg_method]
    pub fn id_i8(&self, x: i8) -> i8 {
        x
    }

    #[jsg_method]
    pub fn id_u16(&self, x: u16) -> u16 {
        x
    }

    #[jsg_method]
    pub fn id_i16(&self, x: i16) -> i16 {
        x
    }

    /// Saturates, so that the boundary values of `i32` come out of a fast callback.
    #[jsg_method]
    #[expect(clippy::cast_possible_truncation, reason = "saturation is the point")]
    pub fn to_i32(&self, x: f64) -> i32 {
        x as i32
    }

    /// Saturates, so that the boundary values of `u32` come out of a fast callback.
    #[jsg_method]
    #[expect(clippy::cast_possible_truncation, reason = "saturation is the point")]
    pub fn to_u32(&self, x: f64) -> u32 {
        u32::try_from(x as i64).unwrap_or(if x < 0.0 { 0 } else { u32::MAX })
    }

    #[jsg_method]
    pub fn touch(&self) {
        self.touched.set(self.touched.get() + 1);
    }

    #[jsg_method]
    pub fn touched(&self) -> u32 {
        self.touched.get()
    }

    #[jsg_method]
    pub fn panic_on(&self, code: u32) -> u32 {
        assert!(code == 0, "intentional panic in a fast callback");
        code
    }

    #[jsg_method]
    pub fn hypot(a: f64, b: f64) -> f64 {
        a.hypot(b)
    }
}

/// Defines `hot(...)` with `body`, calls it once with `warmup` so V8 collects feedback, optimizes
/// it, and returns the source of the call `hot(args)`.
fn optimized(params: &str, body: &str, warmup: &str, args: &str) -> String {
    format!(
        "function hot({params}) {{ {body} }}
         %PrepareFunctionForOptimization(hot);
         hot({warmup});
         %OptimizeFunctionOnNextCall(hot);
         hot({args})"
    )
}

/// Runs `f` and counts the fast callbacks it ran, or returns `None` for the count in builds
/// without debug assertions, which don't count them.
#[cfg(debug_assertions)]
fn count_fast_calls<T>(f: impl FnOnce() -> T) -> (T, Option<u64>) {
    let before = jsg::fast_api::call_count();
    let result = f();
    (result, Some(jsg::fast_api::call_count() - before))
}

#[cfg(not(debug_assertions))]
fn count_fast_calls<T>(f: impl FnOnce() -> T) -> (T, Option<u64>) {
    (f(), None)
}

fn set_resource(lock: &mut jsg::Lock, ctx: &crate::EvalContext<'_>, base: i32) {
    let resource = jsg::Rc::new(FastResource {
        base,
        touched: Cell::new(0),
    });
    ctx.set_global(lock, "r", resource);
    let constructor = jsg::resource::function_template_of::<FastResource>(lock);
    ctx.set_global(lock, "FastResource", constructor);
}

#[test]
fn function_lengths_follow_compat_flag_with_fast_api_enabled() {
    for (enabled, expected) in [(false, "0,0,0,0"), (true, "2,1,0,2")] {
        let harness = crate::Harness::with_fast_api_and_flags(|mut flags| {
            flags.set_spec_compliant_property_attributes(enabled);
        });
        harness.run_in_context(|lock, ctx| {
            set_resource(lock, ctx, 0);
            let lengths = ctx
                .eval::<String>(
                    lock,
                    "[r.add.length, r.idI32.length, r.touch.length, FastResource.hypot.length].join()",
                )
                .unwrap();
            assert_eq!(lengths, expected);
            let (result, fast_calls) = count_fast_calls(|| {
                ctx.eval::<i32>(
                    lock,
                    &optimized("a, b", "return r.add(a, b);", "1, 2", "3, 4"),
                )
                .unwrap()
            });
            assert_eq!(result, 7);
            assert_ne!(fast_calls, Some(0));
            Ok(())
        });
    }
}

#[test]
fn instance_method_takes_fast_path() {
    let harness = crate::Harness::with_fast_api();
    harness.run_in_context(|lock, ctx| {
        set_resource(lock, ctx, 100);
        let (result, fast_calls) = count_fast_calls(|| {
            ctx.eval::<i32>(
                lock,
                &optimized("a, b", "return r.add(a, b);", "1, 2", "3, 4"),
            )
            .unwrap()
        });
        assert_eq!(result, 107);
        assert_ne!(fast_calls, Some(0));
        Ok(())
    });
}

#[test]
fn void_method_takes_fast_path() {
    let harness = crate::Harness::with_fast_api();
    harness.run_in_context(|lock, ctx| {
        set_resource(lock, ctx, 0);
        let (touched, fast_calls) = count_fast_calls(|| {
            ctx.eval::<u32>(
                lock,
                &format!("{}; r.touched()", optimized("", "r.touch();", "", "")),
            )
            .unwrap()
        });
        assert_eq!(touched, 2);
        assert_ne!(fast_calls, Some(0));
        Ok(())
    });
}

#[test]
fn static_method_takes_fast_path() {
    let harness = crate::Harness::with_fast_api();
    harness.run_in_context(|lock, ctx| {
        set_resource(lock, ctx, 0);
        let (result, fast_calls) = count_fast_calls(|| {
            ctx.eval::<f64>(
                lock,
                &optimized("a, b", "return FastResource.hypot(a, b);", "1, 1", "3, 4"),
            )
            .unwrap()
        });
        assert!((result - 5.0).abs() < f64::EPSILON);
        assert_ne!(fast_calls, Some(0));
        Ok(())
    });
}

#[test]
fn no_fast_path_unless_enabled() {
    let harness = crate::Harness::new();
    harness.run_in_context(|lock, ctx| {
        set_resource(lock, ctx, 100);
        let (result, fast_calls) = count_fast_calls(|| {
            ctx.eval::<i32>(
                lock,
                &optimized("a, b", "return r.add(a, b);", "1, 2", "3, 4"),
            )
            .unwrap()
        });
        assert_eq!(result, 107);
        assert_eq!(fast_calls.unwrap_or(0), 0);
        Ok(())
    });
}

/// Each case gives the same result or error on both paths, and takes the fast path if `expect_fast`.
#[test]
fn fast_and_slow_paths_agree() {
    let cases = [
        ("idI32", "1", "7", true),
        ("idI32", "1", "-7", true),
        ("idI32", "1", "1.9", true),
        ("idI32", "1", "-1.9", true),
        ("idI32", "1", "-0", true),
        ("idI32", "1", "NaN", true),
        ("idI32", "1", "Infinity", true),
        ("idI32", "1", "2 ** 31", true),
        ("idI32", "1", "2 ** 31 - 0.5", true),
        ("idI32", "1", "-(2 ** 31) - 0.5", true),
        ("idI32", "1", "'7'", false),
        ("idI32", "1", "({ valueOf() { return 3; } })", false),
        ("idI32", "1", "undefined", false),
        ("idU32", "1", "2 ** 32 - 1", true),
        ("idU32", "1", "2 ** 32", true),
        ("idU32", "1", "2 ** 32 - 0.5", true),
        ("idU32", "1", "-1", true),
        ("idU32", "1", "-0.5", true),
        ("idU32", "1", "NaN", true),
        ("idU8", "1", "255", true),
        ("idU8", "1", "255.5", true),
        ("idU8", "1", "256", true),
        ("idU8", "1", "-1", true),
        ("idU8", "1", "-0.5", true),
        ("idU8", "1", "NaN", true),
        ("idU8", "1", "'7'", false),
        ("idI16", "1", "-32768", true),
        ("idI16", "1", "-32769", true),
        ("idI16", "1", "1.9", true),
        ("idI16", "1", "Infinity", true),
        ("idI8", "1", "-128", true),
        ("idI8", "1", "-128.5", true),
        ("idI8", "1", "128", true),
        ("idU16", "1", "65535", true),
        ("idU16", "1", "65536", true),
        ("idU16", "1", "-1", true),
        ("idF64", "0.5", "-2.25", true),
        ("idF64", "0.5", "NaN", true),
        ("idF64", "0.5", "-Infinity", true),
        ("idF64", "0.5", "'2.5'", false),
        ("idF64", "0.5", "undefined", false),
        ("idBool", "true", "false", true),
        ("idBool", "true", "0", true),
        ("idBool", "true", "'yes'", true),
        ("idBool", "true", "null", true),
    ];

    for (method, warmup, arg, expect_fast) in cases {
        let source = optimized("x", &format!("return String(r.{method}(x));"), warmup, arg);
        let slow = crate::Harness::new();
        let mut slow_result = None;
        slow.run_in_context(|lock, ctx| {
            set_resource(lock, ctx, 0);
            slow_result = Some(
                ctx.eval::<String>(lock, &source)
                    .map_err(|e| e.unwrap_jsg_err(lock).message),
            );
            Ok(())
        });

        let fast = crate::Harness::with_fast_api();
        fast.run_in_context(|lock, ctx| {
            set_resource(lock, ctx, 0);
            let (fast_result, fast_calls) = count_fast_calls(|| {
                ctx.eval::<String>(lock, &source)
                    .map_err(|e| e.unwrap_jsg_err(lock).message)
            });
            assert_eq!(Some(fast_result), slow_result, "{method}({arg})");
            if let Some(fast_calls) = fast_calls {
                let took_fast_path = fast_calls > 0;
                assert_eq!(
                    took_fast_path, expect_fast,
                    "{method}({arg}): fast path taken = {took_fast_path}"
                );
            }
            Ok(())
        });
    }
}

/// An integer comes out of a fast callback as V8's `int32_t` or `uint32_t`, which makes the
/// same number as the slow path does, over the whole range of the type: `i32::MIN`, `u32::MAX`
/// and the other values beyond the Smi range included.
#[test]
fn integer_returns_take_fast_path() {
    let cases = [
        ("toI32", "-(2 ** 31)", "-2147483648"),
        ("toI32", "2 ** 31 - 1", "2147483647"),
        ("toI32", "2 ** 40", "2147483647"),
        ("toI32", "-7.9", "-7"),
        ("toU32", "2 ** 32 - 1", "4294967295"),
        ("toU32", "2 ** 31", "2147483648"),
        ("toU32", "-5", "0"),
        ("idU8", "255", "255"),
        ("idU8", "0", "0"),
        ("idI16", "-32768", "-32768"),
        ("idI16", "32767", "32767"),
        ("idI8", "-128", "-128"),
        ("idI8", "127", "127"),
        ("idU16", "65535", "65535"),
        ("idU16", "0", "0"),
    ];
    for (method, arg, expected) in cases {
        let harness = crate::Harness::with_fast_api();
        harness.run_in_context(|lock, ctx| {
            set_resource(lock, ctx, 0);
            let (result, fast_calls) = count_fast_calls(|| {
                ctx.eval::<String>(
                    lock,
                    &optimized(
                        "x",
                        &format!("const v = r.{method}(x); return typeof v + ' ' + String(v);"),
                        "1",
                        arg,
                    ),
                )
                .unwrap()
            });
            assert_eq!(result, format!("number {expected}"), "{method}({arg})");
            assert_ne!(fast_calls, Some(0), "{method}({arg})");
            Ok(())
        });
    }
}

/// A fast callback passes an `f64` through as V8's `double`, so `-0` keeps its sign.
#[test]
fn f64_keeps_negative_zero_on_the_fast_path() {
    let harness = crate::Harness::with_fast_api();
    harness.run_in_context(|lock, ctx| {
        set_resource(lock, ctx, 0);
        let (negative, fast_calls) = count_fast_calls(|| {
            ctx.eval::<bool>(
                lock,
                &optimized("x", "return Object.is(r.idF64(x), -0);", "1", "-0"),
            )
            .unwrap()
        });
        assert!(negative);
        assert_ne!(fast_calls, Some(0));
        Ok(())
    });
}

/// V8 checks the receiver against the method's signature before a fast call, so a wrong receiver
/// goes to the slow callback, which throws.
#[test]
fn wrong_receiver_takes_slow_path_and_throws() {
    let harness = crate::Harness::with_fast_api();
    harness.run_in_context(|lock, ctx| {
        set_resource(lock, ctx, 0);
        let (err, fast_calls) = count_fast_calls(|| {
            ctx.eval::<i32>(
                lock,
                &optimized(
                    "o",
                    "return FastResource.prototype.idI32.call(o, 1);",
                    "r",
                    "{}",
                ),
            )
            .unwrap_err()
            .unwrap_jsg_err(lock)
        });
        assert_eq!(err.name, ExceptionType::TypeError);
        assert!(
            err.message.to_lowercase().contains("illegal invocation"),
            "unexpected error message: {}",
            err.message
        );
        assert_eq!(fast_calls.unwrap_or(0), 0);
        Ok(())
    });
}

#[test]
fn panic_in_fast_callback_is_an_internal_error() {
    let harness = crate::Harness::with_fast_api();
    harness.run_in_context(|lock, ctx| {
        set_resource(lock, ctx, 0);
        let (err, fast_calls) = count_fast_calls(|| {
            ctx.eval::<u32>(
                lock,
                &optimized("code", "return r.panicOn(code);", "0", "1"),
            )
            .unwrap_err()
            .unwrap_jsg_err(lock)
        });
        assert_ne!(fast_calls, Some(0));
        assert!(
            err.message.contains("internal error"),
            "unexpected error message: {:?}",
            err.message
        );
        assert!(
            !err.message.contains("intentional panic"),
            "raw panic message must not be exposed to JS, got: {:?}",
            err.message
        );
        Ok(())
    });
}
